-- ---------------------------------------------------------------- defaults

function M.defaults()
  local d = { rom_name = "" } -- rom_name: kept from a decoded string, we always write an empty one
  for _, o in ipairs(ALL) do d[o.id] = o.default end
  return d
end

-- ---------------------------------------------------------------- crc32 and base64

local CRC = {}
for i = 0, 255 do
  local c = i
  for _ = 1, 8 do
    if c & 1 == 1 then c = 0xEDB88320 ~ (c >> 1) else c = c >> 1 end
  end
  CRC[i] = c
end

local function crc32(bytes, n)
  local c = 0xFFFFFFFF
  for i = 1, n do c = CRC[(c ~ bytes[i]) & 0xFF] ~ (c >> 8) end
  return c ~ 0xFFFFFFFF
end
M._crc32 = crc32

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64_INV = {}
for i = 1, #B64 do B64_INV[B64:byte(i)] = i - 1 end

local function b64_encode(bytes)
  local out, n = {}, #bytes
  for i = 1, n, 3 do
    local a, b, c = bytes[i], bytes[i + 1], bytes[i + 2]
    local v = (a << 16) | ((b or 0) << 8) | (c or 0)
    local c1, c2, c3, c4 = (v >> 18) & 63, (v >> 12) & 63, (v >> 6) & 63, v & 63
    out[#out + 1] = B64:sub(c1 + 1, c1 + 1) .. B64:sub(c2 + 1, c2 + 1)
      .. (b and B64:sub(c3 + 1, c3 + 1) or "=") .. (c and B64:sub(c4 + 1, c4 + 1) or "=")
  end
  return table.concat(out)
end

-- strict standard base64 with padding; nil on any irregularity
local function b64_decode(s)
  if #s == 0 or #s % 4 ~= 0 then return nil end
  local bytes = {}
  for i = 1, #s, 4 do
    local last = i + 3 == #s
    local v, pad = 0, 0
    for j = 0, 3 do
      local ch = s:byte(i + j)
      local x = B64_INV[ch]
      if x then
        if pad > 0 then return nil end
        v = (v << 6) | x
      elseif ch == 61 and last and j >= 2 then
        pad = pad + 1
        v = v << 6
      else
        return nil
      end
    end
    bytes[#bytes + 1] = (v >> 16) & 0xFF
    if pad < 2 then bytes[#bytes + 1] = (v >> 8) & 0xFF end
    if pad < 1 then bytes[#bytes + 1] = v & 0xFF end
  end
  return bytes
end
M._b64_encode, M._b64_decode = b64_encode, b64_decode

-- ---------------------------------------------------------------- encode

local function clamp(v, lo, hi)
  v = math.tointeger(v) or math.tointeger(math.floor(tonumber(v) or 0)) or 0
  if v < lo then return lo end
  if v > hi then return hi end
  return v
end

local function index_of(list, v)
  for i, x in ipairs(list) do if x == v then return i end end
end

-- value of option o in opts, normalised (missing or invalid -> default)
local function value_of(o, opts)
  local v = opts[o.id]
  if o.kind == "bool" then
    if v == nil then return o.default end
    return v and true or false
  elseif o.kind == "enum" then
    if index_of(o.choices, v) then return v end
    return o.default
  else
    if v == nil then return o.default end
    return clamp(v, o.min, o.max)
  end
end

function M.encode(opts)
  opts = opts or {}
  local d = {}
  for i = 1, M.DATA_LENGTH do d[i] = 0 end
  local function put(byte, v) d[byte + 1] = d[byte + 1] | v end

  for _, o in ipairs(ALL) do
    local at, v = o.at, value_of(o, opts)
    if o.kind == "bool" then
      if at.invert then v = not v end
      if v then put(at.byte, 1 << at.bit) end
    elseif o.kind == "enum" then
      local i = index_of(o.choices, v)
      if at.lookup then
        put(at.byte, i - 1)
      else
        put(at.byte, 1 << at.bits[i])
      end
    elseif at.special == "bst_min" then
      put(58, (v >> 8) & 0x0F)
      put(59, v & 0xFF)
    elseif at.special == "bst_max" then
      put(58, (v >> 4) & 0xF0)
      put(60, v & 0xFF)
    elseif at.size == 2 then
      put(at.byte, v & 0xFF)
      put(at.byte + 1, (v >> 8) & 0xFF)
    else
      local raw = v - (at.bias or 0)
      local mask = (1 << (at.bits or 8)) - 1
      put(at.byte, (raw & mask) << (at.shift or 0))
    end
  end

  local name = tostring(opts.rom_name or ""):gsub("[^\32-\126]", "?"):sub(1, 255)
  d[#d + 1] = #name
  for i = 1, #name do d[#d + 1] = name:byte(i) end
  local crc = crc32(d, #d)
  d[#d + 1] = (crc >> 24) & 0xFF
  d[#d + 1] = (crc >> 16) & 0xFF
  d[#d + 1] = (crc >> 8) & 0xFF
  d[#d + 1] = crc & 0xFF
  for _ = 1, 4 do d[#d + 1] = 0 end
  return M.VERSION .. b64_encode(d)
end

-- ---------------------------------------------------------------- decode

function M.decode(str)
  if type(str) ~= "string" then return nil, "bad_input" end
  if str:sub(1, 3) ~= M.VERSION then return nil, "bad_version" end
  local d = b64_decode(str:sub(4))
  if not d then return nil, "bad_base64" end
  local len = #d
  -- 69 data bytes, name length, name, 4 checksum, 4 padding
  if len < M.DATA_LENGTH + 1 + 8 then return nil, "bad_length" end
  local name_len = d[M.DATA_LENGTH + 1]
  if len ~= M.DATA_LENGTH + 1 + name_len + 8 then return nil, "bad_length" end
  local body = len - 8
  local crc = (d[body + 1] << 24) | (d[body + 2] << 16) | (d[body + 3] << 8) | d[body + 4]
  if crc32(d, body) ~= crc then return nil, "bad_checksum" end

  local function byte(i) return d[i + 1] end
  local opts = { rom_name = "" }
  for i = 1, name_len do
    local c = d[M.DATA_LENGTH + 1 + i]
    opts.rom_name = opts.rom_name .. string.char(c)
  end

  for _, o in ipairs(ALL) do
    local at = o.at
    if o.kind == "bool" then
      local v = (byte(at.byte) >> at.bit) & 1 == 1
      if at.invert then v = not v end
      opts[o.id] = v
    elseif o.kind == "enum" then
      if at.lookup then
        local b = byte(at.byte)
        if o.id == "starters_single_type" then
          b = b & 0x1F
          opts[o.id] = (b >= 1 and b <= #TYPES) and o.choices[b + 1] or "none"
        else
          if b + 1 > #o.choices then return nil, "bad_value" end
          opts[o.id] = o.choices[b + 1]
        end
      else
        -- like the engine: the first set bit in choice order wins; none set -> first choice
        local pick, set = 1, 0
        for i, bit in ipairs(at.bits) do
          if (byte(at.byte) >> bit) & 1 == 1 then
            set = set + 1
            if set == 1 then pick = i end
          end
        end
        if set > 1 then return nil, "bad_value" end -- the engine refuses "more than one value chosen"
        opts[o.id] = o.choices[pick]
      end
    elseif at.special == "bst_min" then
      opts[o.id] = ((byte(58) & 0x0F) << 8) + byte(59)
    elseif at.special == "bst_max" then
      opts[o.id] = ((byte(58) & 0xF0) << 4) + byte(60)
    elseif at.size == 2 then
      opts[o.id] = byte(at.byte) | (byte(at.byte + 1) << 8)
    else
      local raw = (byte(at.byte) >> (at.shift or 0)) & ((1 << (at.bits or 8)) - 1)
      if at.signed and raw >= 128 then raw = raw - 256 end
      opts[o.id] = raw + (at.bias or 0)
    end
  end
  return opts
end

return M

end
__mod["games"] = function(...)
-- Games the engine supports (main games of Gen 1 to 7), as the text identifiers Uzume reads from the game file
-- (hub gamecode.go): gb/gbc = header title, gba/nds = 4-character game code, 3ds = 16-digit program ID.
-- Codes follow the manifest rule: globs, `*` any run, `?` one character, case-insensitive.
local M = {}

M.games = {
  -- Gen 1: header title at 0x134 (Red, Blue, Green in all language versions; Yellow is CGB-flagged, so Uzume
  -- keeps only 11 characters of its title, hence the glob).
  { system = "gb", codes = { "POKEMON RED", "POKEMON BLUE", "POKEMON GREEN", "POKEMON YEL*" } },
  -- Gen 2: header titles (11 characters, CGB-flagged). Yellow is listed again because Uzume may file it as gbc.
  { system = "gbc", codes = { "POKEMON_GLD", "POKEMON_SLV", "PM_CRYSTAL", "POKEMON YEL*" } },
  -- Gen 3: Ruby, Sapphire, Emerald, FireRed, LeafGreen (all language versions).
  { system = "gba", codes = {
    "AXVD", "AXVE", "AXVF", "AXVI", "AXVJ", "AXVS",
    "AXPD", "AXPE", "AXPF", "AXPI", "AXPJ", "AXPS",
    "BPED", "BPEE", "BPEF", "BPEI", "BPEJ", "BPES", "BPET",
    "BPRD", "BPRE", "BPRF", "BPRI", "BPRJ", "BPRS",
    "BPGD", "BPGE", "BPGF", "BPGI", "BPGJ", "BPGS",
  } },
  -- Gen 4 and 5: Diamond, Pearl, Platinum, HeartGold, SoulSilver, Black, White, Black 2, White 2.
  { system = "nds", codes = {
    "ADAD", "ADAE", "ADAF", "ADAI", "ADAJ", "ADAK", "ADAS",
    "APAD", "APAE", "APAF", "APAI", "APAJ", "APAK", "APAS",
    "CPUD", "CPUE", "CPUF", "CPUI", "CPUJ", "CPUK", "CPUS",
    "IPKD", "IPKE", "IPKF", "IPKI", "IPKJ", "IPKK", "IPKS",
    "IPGD", "IPGE", "IPGF", "IPGI", "IPGJ", "IPGK", "IPGS",
    "IRBD", "IRBF", "IRBI", "IRBJ", "IRBK", "IRBO", "IRBS",
    "IRAD", "IRAF", "IRAI", "IRAJ", "IRAK", "IRAO", "IRAS",
    "IRED", "IREF", "IREI", "IREJ", "IREK", "IREO", "IRES",
    "IRDD", "IRDF", "IRDI", "IRDJ", "IRDK", "IRDO", "IRDS",
  } },
  -- Gen 6 and 7: program ID of the base game (X, Y, Omega Ruby, Alpha Sapphire, Sun, Moon, Ultra Sun, Ultra Moon).
  { system = "3ds", codes = {
    "0004000000055D00", "0004000000055E00", "000400000011C400", "000400000011C500",
    "0004000000164800", "0004000000175E00", "00040000001B5000", "00040000001B5100",
  } },
}

local function glob_match(pattern, text)
  local lua = pattern:upper():gsub("[%^%$%(%)%%%.%[%]%+%-]", "%%%0"):gsub("%*", ".*"):gsub("%?", ".")
  return text:upper():match("^" .. lua .. "$") ~= nil
end

--- True when the game (system, code as in the host event detail.game) is on the list.
function M.supported(system, code)
  if type(system) ~= "string" or type(code) ~= "string" or code == "" then return false end
  for _, entry in ipairs(M.games) do
    if entry.system == system then
      for _, c in ipairs(entry.codes) do
        if glob_match(c, code) then return true end
      end
    end
  end
  return false
end

return M

end
__mod["main"] = function(...)
-- Entry module of the Randomizer plugin: hands presets (built in and the person's own) and supported games to
-- Uzume (uz.variants.register), shows a status card in the game detail and the options editor on the screen
-- slot. Uzume draws the dialogs, the variant list and the builds.
local presets = require("presets")
local games = require("games")
local card = require("card")
local editor = require("editor")
local own_presets = require("own_presets")

local uz = uz
local t = uz.i18n.t

uz.log.info(t("loaded", { version = (uz.plugin and uz.plugin.version) or "?" }))

local function preset_list()
  local list = {}
  for _, id in ipairs(presets.order) do
    list[#list + 1] = {
      id = id,
      label = t("preset_" .. id .. "_label"),
      hint = t("preset_" .. id .. "_hint"),
      settings = presets.settings[id],
    }
  end
  return list
end

local function game_list()
  local list = {}
  for _, entry in ipairs(games.games) do
    local codes = {}
    for i, c in ipairs(entry.codes) do codes[i] = c end
    list[#list + 1] = { system = entry.system, codes = codes }
  end
  return list
end

-- Host event source: "uz" since Uzume 0.22; older apps only know "fb".
local host = rawget(_ENV, "uz") ~= nil and "uz" or "fb"

local own = own_presets.new({
  store = uz.store,
  variants = uz.variants,
  builtin = preset_list,
  games = game_list,
  hint = t("own_hint"),
  register_failed = function(err) return t("register_failed", { error = err }) end,
  log = function(level, text)
    if level == "error" then uz.log.error(text) else uz.log.warn(text) end
  end,
})

local state = editor.new_state()

local function context()
  local builtins = {}
  for _, id in ipairs(presets.order) do builtins[#builtins + 1] = { id = id, label = t("preset_" .. id .. "_label") } end
  return { builtins = builtins, own = own.list, can_save = own:available(), max_own = own_presets.MAX }
end

local function render()
  local ok, err = pcall(function() uz.ui.set("screen", editor.build(t, state, context())) end)
  if not ok then uz.log.error(tostring(err)) end
end

local function toast(tone, title, text)
  pcall(uz.ui.notify, { tone = tone, title = title, text = text })
end

-- Once at load, also in the shell context (no game running). The built-in presets are registered even when
-- the store cannot be read.
own:reload()
own:register()
render()

-- Variants and engine state for the card. Both calls are optional (older apps, shell context without a game):
-- a missing function or a failed call leaves that part out of the card.
local function card_info(game)
  local info = {}
  local v = uz.variants
  if type(v.engine) == "function" then
    local ok, e = pcall(v.engine)
    if ok and type(e) == "table" then info.engine = e end
  end
  -- The list needs the game id from detail.game (Uzume 22); without it (older apps) the list is left out.
  if type(v.list) == "function" and game.id ~= nil then
    local ok, l = pcall(v.list, game.id)
    if ok and type(l) == "table" then info.variants = l end
  end
  return info
end

local current

local function show()
  if current then uz.ui.set("detail", card.build(t, current, card_info(current))) end
end

uz.events.on(host, "detail.game", function(game)
  if type(game) ~= "table" then
    current = nil
    uz.ui.clear("detail")
    return
  end
  current = game
  show()
end)

-- A build changed state: refresh the card (the event carries no game data we use).
uz.events.on(host, "variants.state", function() pcall(show) end)

-- ---------------------------------------------------------------- options editor

local function forget_missing_preset()
  if state.editing and not own:find(state.editing) then
    state.editing, state.snapshot = nil, nil
    state.base = "default"
  end
end

local function load_state_from(settings, base, editing, name)
  local ok = editor.load_settings(state, settings)
  if not ok then return false end
  state.base, state.editing, state.name = base, editing, name or ""
  state.snapshot = editing and { name = name, settings = settings } or nil
  return true
end

local function pick_base(value)
  if value == "default" then
    local tab = state.tab
    state = editor.new_state()
    state.tab = tab
    return
  end
  local kind, id = tostring(value):match("^(%a+):(.+)$")
  if kind == "preset" and presets.settings[id] then
    load_state_from(presets.settings[id][presets.SETTINGS_VERSION], value, nil, "")
  elseif kind == "own" and own:find(id) then
    local p = own:find(id)
    load_state_from(p.settings, value, id, p.name)
  end
end

local SAVE_ERRORS = {
  conflict = { "warning", "toast_conflict_title", "toast_conflict_text" },
  too_large = { "warning", "toast_failed_title", "toast_too_large" },
  quota_exceeded = { "warning", "toast_failed_title", "toast_quota" },
  limit = { "warning", "toast_failed_title", "toast_limit" },
  no_store = { "warning", "toast_failed_title", "toast_no_store" },
  not_found = { "warning", "toast_failed_title", "toast_gone" },
}

local function save_failed(code)
  local e = SAVE_ERRORS[code] or { "warning", "toast_failed_title", "toast_failed" }
  toast(e[1], t(e[2]), t(e[3]))
  forget_missing_preset()
  render()
end

local function tab_index(value)
  local n = editor.to_int(value)
  return n and n >= 1 and n <= 12 and n or 1
end

local function refresh_save_buttons()
  if not own:available() then return end
  local disabled = editor.valid_name(state.name) == nil
  local ok = pcall(function()
    uz.ui.patch("screen", "save", { disabled = disabled or #own.list >= own_presets.MAX })
    if state.editing then uz.ui.patch("screen", "save_changes", { disabled = disabled }) end
  end)
  if not ok then render() end
end

-- The preset being edited is still as it was when it was loaded (no other PC changed or deleted it).
local function snapshot_current()
  local cur, snap = state.editing and own:find(state.editing), state.snapshot
  return cur ~= nil and snap ~= nil and cur.name == snap.name and cur.settings == snap.settings
end

local function handle(action, value)
  if action == "edit_options" then
    pcall(uz.ui.open, "screen")
  elseif action == "tab" then
    state.tab = tab_index(value)
    render()
  elseif action == "base" then
    pick_base(value)
    render()
  elseif action == "load_own" then
    if own:find(value) then pick_base("own:" .. tostring(value)) end
    render()
  elseif action:sub(1, 4) == "set:" then
    if editor.set_option(state, action:sub(5), value) then render() end
  elseif action == "string" then
    if editor.paste(state, value) ~= "same" then render() end
  elseif action == "name" then
    state.name = type(value) == "string" and value or ""
    refresh_save_buttons()
  elseif action == "save_new" or action == "save_changes" then
    local name = editor.valid_name(state.name)
    if not name or (action == "save_changes" and not state.editing) then return end
    if action == "save_changes" and not snapshot_current() then
      toast("warning", t("toast_conflict_title"), t("toast_changed_text"))
      return
    end
    local id, code
    if action == "save_new" then
      id, code = own:add(name, editor.current_string(state))
    elseif state.editing then
      id, code = own:update(state.editing, name, editor.current_string(state))
      if id then id = state.editing end
    end
    if not id then return save_failed(code) end
    state.editing, state.base, state.name = id, "own:" .. id, name
    state.snapshot = { name = name, settings = editor.current_string(state) }
    toast("info", t("toast_saved"), name)
    render()
  elseif action == "delete" then
    if not state.editing then return end
    if not snapshot_current() then
      toast("warning", t("toast_conflict_title"), t("toast_changed_text"))
      return
    end
    local gone = own:find(state.editing)
    local ok, code = own:remove(state.editing)
    if not ok then return save_failed(code) end
    state.editing, state.base, state.name, state.snapshot = nil, "default", "", nil
    toast("info", t("toast_deleted"), gone and gone.name or t("own_hint"))
    render()
  end
end

uz.ui.on_action(function(action, value)
  local ok, err = pcall(handle, tostring(action), value)
  if not ok then uz.log.error(tostring(err)) end
end)

-- The store has a newer version of the presets (another PC): read it, register again, keep the editor state.
uz.events.on("app", "store.changed", function(key)
  if key ~= own_presets.KEY then return end
  own:reload()
  own:register()
  forget_missing_preset()
  render()
end)

-- Both versions are kept until the next save: tell the person, never overwrite silently.
uz.events.on("app", "store.conflict", function(key)
  if key ~= own_presets.KEY then return end
  toast("warning", t("toast_conflict_title"), t("toast_conflict_text"))
end)

-- Reloaded plugin: take the presets from the store again.
uz.events.on(host, "reloaded", function()
  own:reload()
  own:register()
  forget_missing_preset()
  render()
end)

end
__mod["own_presets"] = function(...)
-- The person's own presets: kept in uz.store under the key "presets" (array of { id, name, settings }) and
-- handed to Uzume together with the built-in presets by uz.variants.register.
-- Every write carries the revision that was read; a stale write is refused (never overwritten silently).
local M = {}

M.KEY = "presets"
M.MAX = 29 -- 3 built-in presets + 29 of their own = the 32 Uzume accepts

local Own = {}
Own.__index = Own

--- env = { store = uz.store | nil, variants = uz.variants, builtin = fn() -> presets, games = fn() -> games,
---         hint = text, register_failed = fn(error) -> text, log = fn(level, text) }
function M.new(env)
  return setmetatable({ env = env, list = {}, revision = 0 }, Own)
end

local function log(self, level, text)
  if self.env.log then self.env.log(level, text) end
end

local function clean(entry)
  if type(entry) ~= "table" then return nil end
  local id, name, settings = entry.id, entry.name, entry.settings
  if type(id) ~= "string" or not id:match("^own%-%d+$") or #id > 32 then return nil end
  if type(name) ~= "string" or name == "" or (utf8.len(name) or 61) > 60 then return nil end
  if type(settings) ~= "string" or #settings > 4096 or not settings:match("^%d%d%d[A-Za-z0-9+/=]+$") then return nil end
  return { id = id, name = name, settings = settings }
end

--- Can presets be saved (older apps have no uz.store)?
function Own:available()
  local s = self.env.store
  return type(s) == "table" and type(s.get) == "function" and type(s.put) == "function"
end

--- Reads the list from the store. Returns true, or nil and a message (the list is then empty).
function Own:reload()
  self.list, self.revision = {}, 0
  if not self:available() then return nil, "no_store" end
  local ok, value, rev = pcall(self.env.store.get, M.KEY)
  if not ok then
    log(self, "error", tostring(value))
    return nil, "failed"
  end
  self.revision = math.tointeger(rev) or 0
  if type(value) == "table" then
    for _, entry in ipairs(value) do
      local e = clean(entry)
      if e and #self.list < M.MAX then self.list[#self.list + 1] = e end
    end
  end
  return true
end

function Own:find(id)
  for _, p in ipairs(self.list) do if p.id == id then return p end end
end

--- Registers the built-in presets and the own ones with the games. Returns true, or nil and the error text.
function Own:register()
  local presets = {}
  for _, p in ipairs(self.env.builtin()) do presets[#presets + 1] = p end
  for _, p in ipairs(self.list) do
    presets[#presets + 1] = { id = p.id, label = p.name, hint = self.env.hint, settings = { [p.settings:sub(1, 3)] = p.settings } }
  end
  local ok, err = pcall(self.env.variants.register, { engine = "randomizer", presets = presets, games = self.env.games() })
  if not ok then
    log(self, "error", self.env.register_failed and self.env.register_failed(tostring(err)) or tostring(err))
    return nil, tostring(err)
  end
  return true
end

local function copy(list)
  local out = {}
  for i, p in ipairs(list) do out[i] = { id = p.id, name = p.name, settings = p.settings } end
  return out
end

-- Writes `list` with the revision that was read. On success the list is adopted and registered; a conflict
-- reloads the store (the attempted version stays as a conflict copy in uz.store) and registers again.
function Own:write(list)
  if not self:available() then return nil, "no_store" end
  local ok, a, b = pcall(self.env.store.put, M.KEY, list, self.revision)
  if not ok then
    log(self, "error", tostring(a))
    return nil, "failed"
  end
  if a == true then
    self.list, self.revision = list, math.tointeger(b) or self.revision
    self:register()
    return true
  end
  if b == "conflict" then
    self:reload()
    self:register()
    return nil, "conflict"
  end
  if b == "too_large" or b == "quota_exceeded" then return nil, b end
  return nil, "failed"
end

local function next_id(list)
  local max = 0
  for _, p in ipairs(list) do
    local n = tonumber(p.id:match("^own%-(%d+)$"))
    if n and n > max then max = n end
  end
  return "own-" .. (max + 1)
end

--- Adds a preset. Returns its id, or nil and "limit", "no_store", "conflict", "too_large", "quota_exceeded", "failed".
function Own:add(name, settings)
  if #self.list >= M.MAX then return nil, "limit" end
  local list = copy(self.list)
  local id = next_id(list)
  list[#list + 1] = { id = id, name = name, settings = settings }
  local ok, code = self:write(list)
  if not ok then return nil, code end
  return id
end

--- Replaces name and settings of an own preset. Returns true, or nil and a code ("not_found" included).
function Own:update(id, name, settings)
  if not self:find(id) then return nil, "not_found" end
  local list = copy(self.list)
  for _, p in ipairs(list) do
    if p.id == id then p.name, p.settings = name, settings end
  end
  return self:write(list)
end

function Own:remove(id)
  if not self:find(id) then return nil, "not_found" end
  local list = {}
  for _, p in ipairs(self.list) do
    if p.id ~= id then list[#list + 1] = { id = p.id, name = p.name, settings = p.settings } end
  end
  return self:write(list)
end

return M

end
__mod["presets"] = function(...)
-- Randomizer presets: settings strings of the Universal Pokemon Randomizer FVX, keyed by settings version.
-- The strings come from the engine's own Settings#toString (see docs/presets.md); they are opaque data here.
local M = {}

-- Settings version (the 3-digit prefix of every string) of the engine release these strings were made for.
M.SETTINGS_VERSION = "428"
M.ENGINE_VERSION = "1.6.2"

-- Order is the order of the Select in the Randomize dialog. Uzume adds "Custom" itself.
M.order = { "nuzlocke", "classic", "chaos" }

M.settings = {
  nuzlocke = { ["428"] = "428wQgEBQgAAAAAAAAEAALkIAIRBBgUAAAUAAIEAAEb/wAAAAAAAADkBOQBAAgJ5AAAAOQAAgBBAAEBABAAkAAJAgAAKAEAAAi+E08AAAAA" },
  classic = { ["428"] = "428AQgEBQgAAAAAAAAEAALkBAARBAIUAAAUAAICAAEa/wAAAAAAAADkBOQBAAgJ5AAAAOQABQABAAEBAAAAAAAJAAAAKAEAAKNh4usAAAAA" },
  chaos = { ["428"] = "428gQICBnIAAAAAAAARAALkBAARHERJAQBJABEJDwIQ/wAAAAAAAADkieTBAAgJ5AAAAOQXAQABAAEBBAAAAAAJAAAAKAEAALGZzKAAAAAA" },
}

return M

end
